(()=>{'use strict';
const I=window.STUDY_INDEX,R=window.CFA_RECAP,B=window.CFA_SOURCE_BANK,$=id=>document.getElementById(id),root=$('main');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=x=>Number(x).toLocaleString('vi-VN');
const read=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}},write=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));return true}catch{return false}};
const KEY='cfa26-studyhub:v14',OLD='cfa26-studyhub:interface:v63',PK='cfa26-private-study-v135';let S={done:{},last:null,language:'both',dark:false,...read(KEY,{})};
const legacy=read(OLD,{});if(!read(KEY,null))S.dark=!!legacy.dark;
const save=()=>write(KEY,S);const progress=()=>read(PK,{});
const names=[['Định lượng','QM'],['Kinh tế học','EC'],['Tài chính doanh nghiệp','CI'],['Phân tích báo cáo tài chính','FSA'],['Đầu tư cổ phiếu','EQ'],['Trái phiếu','FI'],['Phái sinh','DE'],['Đầu tư thay thế','AI'],['Quản lý danh mục','PM'],['Đạo đức nghề nghiệp','ETH']];
const subjects=names.map((v,i)=>{let code=String(i+1).padStart(2,'0'),modules=I.filter(m=>m.subject_code===code);return{code,vi:v[0],short:v[1],en:modules[0].subject,modules}}), SM=Object.fromEntries(subjects.map(s=>[s.code,s])), M=Object.fromEntries(I.map(m=>[m.id,m])), L=Object.fromEntries(I.flatMap(m=>m.los.map(l=>[l.id,m]))), O=Object.fromEntries(B.outline.map(x=>[x.id,x]));
const moduleId=e=>M[e.module_id]?e.module_id:L[e.los]?.id||null;
const unique=rows=>{const seen=new Set();return rows.filter(e=>{const k=[e.source,e.page,e.number,e.answer,e.answerPage].join('|');if(seen.has(k))return false;seen.add(k);return true})};
const all=unique(B.items),allRecords=B.items,itemsByModule=new Map(),mockBySource=new Map();for(const e of all){const mid=moduleId(e);if(mid){if(!itemsByModule.has(mid))itemsByModule.set(mid,[]);itemsByModule.get(mid).push(e)}if(B.files[e.source]?.group==='Mock Test'){if(!mockBySource.has(e.source))mockBySource.set(e.source,[]);mockBySource.get(e.source).push(e)}}
const sourceLabel=g=>({'CFAI Curriculum':'CFA Institute','Kaplan QBank':'Kaplan Question Bank','Bonus QBank':'Question Bank bổ sung','Mock Test':'Mock Test','SAPP Slides':'SAPP Slides','Kaplan SchweserNotes':'SchweserNotes','Revision Mindmap':'Mindmap','CFAI Prerequisite':'Kiến thức nền 2024'}[g]||g);
const group=e=>B.files[e.source]?.group;const isDone=m=>Object.prototype.hasOwnProperty.call(S.done,m.id)?!!S.done[m.id]:m.los.every(l=>legacy.read?.[l.id]);const completed=ms=>ms.filter(isDone).length;const percent=(a,b)=>b?Math.round(100*a/b):0;
const hash=(...v)=>'#'+v.map(encodeURIComponent).join('/');const go=(...v)=>{let h=hash(...v);if(location.hash===h)render();else location.hash=h};
const navs=[['study','Subjects','book'],['library','Library','book'],['practice','Question Bank','check'],['mock','Mock Exams','clock'],['review','Review','review']];
const paths={home:'M3 10l9-7 9 7v10h-6v-7H9v7H3z',book:'M4 4h6a3 3 0 0 1 3 3v13a3 3 0 0 0-3-3H4z M13 7a3 3 0 0 1 3-3h4v13h-4a3 3 0 0 0-3 3',check:'M9 5h12M9 12h12M9 19h12m-18-7 2 2 2-3M3 5h2M3 19h2',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18zm0 4v5l4 2',review:'M3 12a9 9 0 1 0 3-6.7L3 8m0-5v5h5m4-1v5l3 2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8m0-6v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14m5 12 6 6',arrow:'M4 12h16m-6-6 6 6-6 6',back:'M20 12H4m6-6-6 6 6 6',moon:'M20 15a8 8 0 0 1-11-11A9 9 0 1 0 20 15z'};
const icon=k=>`<svg aria-hidden="true" viewBox="0 0 24 24" class="v14-icon"><path d="${paths[k]||paths.book}"/></svg>`;
const link=(label,url,cl='')=>`<a class="v14-btn ${cl}" href="${esc(url)}">${esc(label)}</a>`;
const btn=(label,act,cl='',data='')=>`<button type="button" class="v14-btn ${cl}" data-action="${esc(act)}" ${data}>${esc(label)}</button>`;
const orig=(label,sid,page,cl='quiet')=>B.files[sid]&&page?`<button type="button" class="v14-btn ${cl}" data-private-read="${esc(sid)}" data-page="${Number(page)||1}">${esc(label)}</button>`:'';
const bar=(a,b)=>`<div class="v14-progress" role="progressbar" aria-label="Tiến độ" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${percent(a,b)}"><i style="width:${percent(a,b)}%"></i></div>`;
const pair=(en,vi)=>`<div class="v14-pair">${S.language!=='en'&&vi?`<div lang="vi">${esc(vi)}</div>`:''}${S.language!=='vi'&&en?`<div lang="en" class="v14-en">${esc(en)}</div>`:''}</div>`;
const language=()=>`<label class="v14-language">Ngôn ngữ <select id="language"><option value="both" ${S.language==='both'?'selected':''}>Việt + Anh</option><option value="vi" ${S.language==='vi'?'selected':''}>Tiếng Việt</option><option value="en" ${S.language==='en'?'selected':''}>English</option></select></label>`;
const title=(t,sub='',aside='')=>`<div class="v14-title"><div><h1>${esc(t)}</h1>${sub?`<p>${esc(sub)}</p>`:''}</div>${aside}</div>`;
const crumb=(s,m)=>`<div class="v14-crumb"><a href="#study">Subjects</a> ${s?`<span>›</span> <a href="${hash('subject',s.code)}">${esc(s.en)}</a>`:''}${m?`<span>›</span> <span>LM${m.number}</span>`:''}</div>`;
const section=(heading,body)=>`<section class="v14-section"><h2>${esc(heading)}</h2>${body}</section>`;
function shell(active){document.documentElement.classList.toggle('dark',S.dark);$('v14-nav').innerHTML=`<a href="#home" class="v14-brand"><span class="v14-brand-icon">S</span><span><strong>Study Hub</strong><small>CFA Level I · 2026</small></span></a><nav aria-label="Menu chính">${navs.map(([k,t,ic])=>`<a class="v14-navlink ${active===k?'selected':''}" ${active===k?'aria-current="page"':''} href="#${k}">${icon(ic)}<span>${t}</span></a>`).join('')}</nav><div class="v14-navfoot"><a class="v14-navlink ${active==='settings'?'selected':''}" href="#settings">${icon('settings')} Settings</a><span>Study Hub 15.0 · Pilot</span></div>`;$('v14-top').innerHTML=`<div class="v14-topname">${esc(navs.find(x=>x[0]===active)?.[1]||'Settings')}</div><form id="global-search" role="search"><label class="v14-sr" for="search-input">Search modules, concepts or documents</label>${icon('search')}<input id="search-input" name="q" placeholder="Search modules, concepts or documents…" required></form><button class="v14-iconbtn" data-action="theme" title="Đổi giao diện sáng/tối" aria-label="Đổi giao diện sáng/tối">${icon('moon')}</button>`;$('v14-mobile').innerHTML=navs.map(([k,t,ic])=>`<a href="#${k}" class="${active===k?'selected':''}">${icon(ic)}<span>${({study:'Subjects',library:'Library',practice:'Questions',mock:'Mocks',review:'Review'})[k]}</span></a>`).join('')+'<a href="#settings" aria-label="Cài đặt">'+icon('settings')+'<span>Settings</span></a>'}
function subjectCards(){return `<div class="v14-subgrid">${subjects.map(s=>`<a class="v14-subcard" href="${hash('subject',s.code)}"><div class="v14-subtop"><span class="v14-code">${s.short}</span><span>${completed(s.modules)}/${s.modules.length} module</span></div><h3>${esc(s.en)}</h3><p>${esc(s.vi)}</p>${bar(completed(s.modules),s.modules.length)}<span class="v14-enter">${completed(s.modules)?'Tiếp tục học':'Xem các module'} ${icon('arrow')}</span></a>`).join('')}</div>`}
function home(){study()}
function study(){const m=M[S.last?.id]||I[0];root.innerHTML=title('CFA Level I · 2026','Chọn môn học hoặc mở tài liệu gốc.')+`<div class="v141-start"><div><strong>Continue Studying</strong><p>${esc(m.subject)} · ${esc(m.title)}</p></div>${link('Continue',hash('module',m.id,S.last?.tab||'learn',m.id==='CFA26-01-01'&&(!S.last?.tab||S.last?.tab==='learn')?'resume':S.last?.part||0),'primary')}</div><div class="v141-shortcuts">${link('Library — 534 documents','#library','secondary')}${link('Question Bank','#practice')}${link('Mock Exams','#mock')}</div>${section('Subjects',subjectCards())}`}
function subject(code){const s=SM[code];if(!s)return study();root.innerHTML=crumb(s)+title(s.en,s.vi,link('Subject Review',hash('summary',code)))+`<div class="v14-actions">${link('Source Materials',hash('library',code),'secondary')}${link('Question Bank',hash('practice',code))}</div><div class="v14-course-progress"><strong>${completed(s.modules)}/${s.modules.length} module đã học</strong>${bar(completed(s.modules),s.modules.length)}</div><div class="v14-list">${s.modules.map(m=>`<a class="v14-module-row" href="${hash('module',m.id,'learn',0)}"><span class="v14-module-num ${isDone(m)?'done':''}">${isDone(m)?'✓':String(m.number).padStart(2,'0')}</span><div><h3>${esc(m.title)}</h3><p>${m.los.length} LOS · ${fmt(itemsByModule.get(m.id)?.length||0)} mục bài tập nguồn</p></div><span class="v14-module-state">${isDone(m)?'Đã học':S.last?.id===m.id?'Đang học':'Open module'} ${icon('arrow')}</span></a>`).join('')}</div>`}
const tabs=[['learn','Lesson'],['formula','Formulas & Examples'],['recap','Review'],['questions','Practice']];
function sourceLine(m,d){const o=O[m.id],sl=B.slideModules134?.[m.id];return `<section class="v141-sources"><h2>Source Materials</h2><div class="v14-actions">${orig('Read CFAI Curriculum',o?.curriculum?.source||d.source,o?.curriculum?.start||d.coverageAudit?.start,'secondary')}${orig('Read SchweserNotes',o?.kaplan?.source,o?.kaplan?.start,'secondary')}${orig('Read SAPP Slides',sl?.source,sl?.start,'secondary')}${orig('Read Mindmap',B.mindmap134?.[m.subject_code],1,'secondary')}${link('More documents',hash('library',m.subject_code))}</div><p class="v14-hint">Đọc tài liệu gốc ngay tại trang tương ứng. Nội dung nguyên văn cần gói học liệu cá nhân; cũng có thể mở PDF từ máy.</p></section>`}
// Lecture view: use the existing source-reviewed summaries, keep source cards inline.
const ratesLead={
 a:['Money received at different dates is not directly comparable. Interest rates make those cash flows equivalent: from the lender’s perspective, they express the compensation required for postponing consumption; in valuation, the same rate converts a future amount into a present amount. The first step is therefore to understand what a quoted rate represents and which risks are included before comparing investments.','Tiền nhận ở các thời điểm khác nhau không thể so sánh trực tiếp. Lãi suất tạo cơ sở quy đổi các dòng tiền về cùng thời điểm: với người cho vay, đây là khoản bù đắp cho việc trì hoãn tiêu dùng; trong định giá, lãi suất quy đổi khoản tiền tương lai về hiện tại. Vì vậy, trước khi so sánh hai khoản đầu tư, cần hiểu ý nghĩa của lãi suất được công bố và những phần bù rủi ro nằm trong đó.'],
 b:['Once the required return is understood, the next question is how much an investment actually earns. Start with the price change and income over one holding period. For several periods, investment wealth grows from a changing base, so compound growth factors rather than add returns. The arithmetic, geometric and harmonic means answer different questions; the choice depends on whether we want a typical period, accumulated growth, or a ratio such as the average price paid with equal cash contributions.','Sau khi hiểu lợi suất yêu cầu, ta chuyển sang đo lợi suất thực tế của khoản đầu tư. Trong một kỳ nắm giữ, cần tính cả biến động giá lẫn thu nhập. Qua nhiều kỳ, vốn đầu tư đầu kỳ thay đổi vì kết quả của kỳ trước, nên phải nhân các hệ số tăng trưởng thay vì cộng lợi suất. Trung bình số học, trung bình nhân và trung bình điều hòa trả lời những câu hỏi khác nhau: lợi suất một kỳ điển hình, tốc độ tăng trưởng kép, hoặc một tỷ số như giá mua bình quân khi bỏ cùng một số tiền mỗi lần.'],
 c:['An investor’s contributions and withdrawals can change the amount of capital exposed to each period’s return. Money-weighted return therefore evaluates the investor’s experience using dated cash flows. Time-weighted return instead breaks the investment into subperiods at external cash flows, evaluates investment performance separately, then links the results. The distinction is particularly important when evaluating a fund manager who cannot control client deposits and withdrawals.','Khoản tiền nộp thêm hoặc rút ra làm thay đổi số vốn chịu tác động của lợi suất mỗi kỳ. Money-weighted return vì vậy đánh giá kết quả của nhà đầu tư theo thời điểm và quy mô dòng tiền. Time-weighted return tách khoảng đầu tư thành các tiểu kỳ tại dòng tiền bên ngoài, đo hiệu quả từng tiểu kỳ rồi nối các kết quả. Sự khác biệt này đặc biệt quan trọng khi đánh giá nhà quản lý quỹ không quyết định được thời điểm khách hàng nộp hoặc rút tiền.'],
 d:['Returns measured over different horizons must be converted to a common basis before comparison. Nonannual compounding adjusts both the rate per compounding interval and the number of intervals; annualizing a holding-period return instead scales its growth factor to a one-year horizon. Continuous compounding gives another representation of the same growth factor, with the useful property that log returns add over successive periods.','Muốn so sánh các lợi suất có kỳ đo lường khác nhau, trước hết cần quy đổi về cùng một cơ sở. Ghép lãi nhiều lần trong năm đòi hỏi điều chỉnh đồng thời lãi suất mỗi kỳ và số kỳ; năm hóa HPR dùng hệ số tăng trưởng để quy đổi về một năm. Ghép lãi liên tục biểu diễn cùng hệ số tăng trưởng dưới dạng logarit, nhờ đó lợi suất log của các kỳ liên tiếp có thể cộng lại.'],
 e:['A reported return does not necessarily describe what an investor can spend or reinvest. Trading costs, fund expenses, taxes and changes in purchasing power affect the interpretation of that return. Begin by identifying whether the measure is gross or net, pre-tax or after-tax, nominal or real. Finally, distinguish the return on the portfolio from the return on the investor’s equity when borrowed funds or derivatives amplify exposure.','Lợi suất được báo cáo không nhất thiết phản ánh số tiền nhà đầu tư thực sự có thể chi tiêu hoặc tái đầu tư. Chi phí giao dịch, phí quỹ, thuế và sự thay đổi sức mua đều ảnh hưởng đến cách diễn giải lợi suất. Trước tiên, xác định lợi suất đang xét là gross hay net, trước hay sau thuế, danh nghĩa hay thực. Cuối cùng, phân biệt lợi suất của danh mục với lợi suất trên vốn tự có khi việc vay nợ hoặc sử dụng phái sinh làm tăng mức phơi nhiễm.']
};
// Additional teaching explanations paraphrased from CFAI Rates and Returns pp.13–45.
const ratesDetail={
 1:['The three interpretations are not three separate rates. Using the same cash-flow equivalence, an investor who requires 5.26% can discount 10,000 due in one year to 9,500 today; choosing immediate consumption instead means sacrificing that same return. Keep the time interval consistent in all three interpretations.','Ba cách hiểu không phải ba mức lãi suất khác nhau. Với cùng quan hệ tương đương dòng tiền, nhà đầu tư yêu cầu 5,26% sẽ chiết khấu 10.000 nhận sau một năm về 9.500 hôm nay; nếu chọn tiêu dùng ngay thì bỏ qua chính khoản lợi suất đó. Cần giữ thống nhất kỳ hạn trong cả ba cách hiểu.'],
 2:['The premiums represent different sources of compensation. The inflation premium relates to expected inflation over the debt’s life; default risk concerns the borrower’s ability to meet promised payments; liquidity risk concerns the cost of exiting the investment; maturity risk reflects exposure to changing interest rates. A nominal short-term government rate can proxy for the nominal risk-free rate over its own horizon. An annual quote on a 90-day instrument must not be interpreted as the actual 90-day return.','Các phần bù đại diện cho những nguồn bù đắp khác nhau. Inflation premium liên quan đến lạm phát kỳ vọng trong thời hạn khoản nợ; default risk liên quan đến khả năng bên vay thực hiện nghĩa vụ; liquidity risk liên quan đến chi phí thoát khỏi khoản đầu tư; maturity risk phản ánh mức phơi nhiễm khi lãi suất thay đổi. Lãi suất danh nghĩa của công cụ chính phủ ngắn hạn có thể dùng làm đại diện cho lãi suất phi rủi ro danh nghĩa trong kỳ tương ứng. Lãi suất năm được niêm yết cho công cụ 90 ngày không phải lợi suất thực nhận trong 90 ngày.'],
 3:['Separate income yield from capital gain or loss. In the source’s illustration, paying 100 and selling for 105 creates a 5% price gain; receiving 2 in income at the end of the same period adds 2%, so total HPR is 7%. If income is received before the end and reinvested, additional earnings may affect the ending wealth. For a series of holding periods, multiply their growth factors first, then subtract one.','Tách lợi suất từ thu nhập và lãi/lỗ do biến động giá. Trong minh họa của nguồn, mua giá 100 rồi bán giá 105 tạo lãi giá 5%; thu nhập 2 nhận vào cuối cùng kỳ đóng góp thêm 2%, nên HPR tổng là 7%. Nếu nhận thu nhập sớm hơn rồi tái đầu tư, phần lợi tức phát sinh có thể làm thay đổi giá trị cuối kỳ. Với chuỗi nhiều kỳ nắm giữ, nhân các hệ số tăng trưởng trước rồi mới trừ 1.'],
 5:['Exhibit 2 demonstrates why the average return and the rate of wealth growth can disagree. Starting with one unit, the successive returns −50%, +35% and +27% leave 0.85725 units. The arithmetic mean is positive (4%), even though the investment has lost value. The geometric mean gives the annual compound rate that reproduces the actual ending wealth. The difference grows with dispersion in returns; the two means coincide for identical period returns.','Exhibit 2 minh họa vì sao lợi suất bình quân và tốc độ tăng trưởng tài sản có thể khác nhau. Bắt đầu với một đơn vị vốn, lần lượt chịu lợi suất −50%, +35% và +27%, tài sản còn 0,85725 đơn vị. Trung bình số học dương (4%) dù khoản đầu tư bị lỗ. Trung bình nhân cho biết tốc độ tăng trưởng kép mỗi năm tái tạo đúng giá trị cuối kỳ. Chênh lệch giữa hai loại trung bình tăng theo độ phân tán; hai kết quả bằng nhau nếu lợi suất các kỳ giống hệt nhau.'],
 6:['For equal-cash purchases, a lower price buys more units. The relevant average purchase price is total money spent divided by total units acquired, not the mean of quoted prices. With the source’s prices EUR10 and EUR15 and equal cash committed to each purchase, the harmonic mean is EUR12. When applying the harmonic or geometric mean to returns rather than prices or ratios, use positive growth factors (1 + R) and convert the result back to a return.','Khi mỗi lần mua bỏ cùng một số tiền, mức giá thấp cho phép mua nhiều đơn vị hơn. Giá vốn bình quân thích hợp bằng tổng tiền chi chia tổng số đơn vị mua được, không phải trung bình số học của các mức giá niêm yết. Với hai mức giá 10 EUR và 15 EUR trong nguồn và số tiền đầu tư bằng nhau, trung bình điều hòa là 12 EUR. Khi tính trung bình điều hòa hoặc trung bình nhân của lợi suất thay vì giá hoặc tỷ số, dùng hệ số tăng trưởng dương (1 + R), sau đó chuyển kết quả trở lại dạng lợi suất.'],
 7:['When choosing a mean, first decide whether extremes are informative or should have less influence. If the aim is to describe a typical observation with all values included, the arithmetic mean is useful. If the focus is compounding, use the geometric mean. A trimmed mean removes tail observations, whereas a winsorized mean retains the sample count but replaces tail values at specified boundaries. The harmonic mean is useful for positive ratios. These choices are not interchangeable.','Khi chọn loại trung bình, trước tiên xác định các giá trị cực trị có mang thông tin cần giữ hay nên giảm ảnh hưởng. Nếu mục tiêu là mô tả một quan sát điển hình và giữ mọi giá trị, trung bình số học hữu ích. Nếu mục tiêu là đo tăng trưởng kép, dùng trung bình nhân. Trimmed mean loại bỏ quan sát ở hai đuôi, còn winsorized mean giữ số quan sát nhưng thay các giá trị ở đuôi bằng ngưỡng tương ứng. Trung bình điều hòa hữu ích với tỷ số dương. Không thể dùng các phương pháp này thay thế nhau tùy ý.'],
 8:['Exhibit 11 makes the cash-flow convention concrete. At time 0 the investor pays 200; at time 1 a second share costs 225 while the first share distributes 5, so the net cash flow is −220. At time 2 the sale of both shares brings in 470 and dividends add 10, giving +480. Set the present value of these three dated cash flows equal to zero and solve for the IRR, 9.39%. A spreadsheet IRR function can handle these equally spaced periods.','Exhibit 11 làm rõ quy ước dòng tiền. Tại thời điểm 0, nhà đầu tư chi 200; tại thời điểm 1, cổ phiếu thứ hai có giá 225 trong khi cổ phiếu thứ nhất trả cổ tức 5, nên dòng tiền ròng là −220. Tại thời điểm 2, bán cả hai cổ phiếu thu 470 và cổ tức thu thêm 10, tạo dòng tiền +480. Cho tổng hiện giá ba dòng tiền theo thời điểm bằng 0 rồi giải IRR, thu được 9,39%. Có thể dùng hàm IRR trong bảng tính khi các kỳ cách đều nhau.'],
 9:['Use the same dividend-paying stock to compare performance. The first year earns (225 − 200 + 5)/200 = 15%. At the beginning of the second year the two shares are worth 450; ending proceeds plus dividends equal 480, giving 6.67%. Linking these two years and taking the annual compound rate gives 10.76%. MWR is lower because the investor had more capital exposed to the less profitable second year.','Dùng lại cổ phiếu trả cổ tức để so sánh hiệu quả. Năm đầu đạt (225 − 200 + 5)/200 = 15%. Đầu năm thứ hai, hai cổ phiếu có giá trị 450; tiền bán cuối kỳ và cổ tức tổng cộng 480, tương ứng 6,67%. Ghép hai năm rồi lấy tốc độ tăng trưởng kép theo năm được 10,76%. MWR thấp hơn vì nhà đầu tư có nhiều vốn chịu tác động của năm thứ hai, khi lợi suất thấp hơn.'],
 11:['In the monthly-compounding pension example, the quoted 6% annual rate implies a monthly rate of 0.5%. Ten years correspond to 120 monthly compounding periods. Discounting CAD5 million by the resulting factor yields approximately CAD2.748 million. The important step is to adjust both the rate and number of periods; changing one without the other misstates present value.','Trong ví dụ quỹ hưu trí ghép lãi hàng tháng, lãi suất năm niêm yết 6% tương ứng lãi suất tháng 0,5%. Mười năm tương ứng 120 kỳ ghép lãi. Chiết khấu 5 triệu CAD theo hệ số này thu được khoảng 2,748 triệu CAD. Bước quan trọng là điều chỉnh cả lãi suất lẫn số kỳ; chỉ đổi một trong hai sẽ làm sai giá trị hiện tại.'],
 12:['For annualizing a measured return, the exponent expresses how many observed intervals fit in one year. A monthly observation uses 12; a quarterly observation uses 4; a 15-day return under a 365-day convention uses 365/15; an 18-month HPR uses 2/3. The source’s weekly 0.2% illustration yields 10.95% annualized. This is a conversion, not a prediction that the same weekly return will continue.','Khi năm hóa một lợi suất quan sát được, số mũ biểu thị số kỳ đo lường nằm trong một năm. Kỳ tháng dùng 12; kỳ quý dùng 4; lợi suất 15 ngày theo quy ước năm 365 ngày dùng 365/15; HPR 18 tháng dùng 2/3. Minh họa của nguồn: lợi suất tuần 0,2% tương ứng lợi suất năm hóa 10,95%. Đây là phép quy đổi, không phải dự báo lợi suất tuần đó sẽ lặp lại.'],
 16:['The after-tax real return answers how much purchasing power remains after taxes and inflation. In Example 14, a 3% nominal return taxed at 20% gives 2.4% after tax. Dividing the after-tax growth factor 1.024 by the inflation factor 1.02 and subtracting one yields approximately 0.39%. The tax component varies with the investor’s circumstances, so a single reported figure may not apply to all investors.','Lợi suất thực sau thuế cho biết sức mua tăng bao nhiêu sau thuế và lạm phát. Trong Example 14, lợi suất danh nghĩa 3% chịu thuế 20% còn 2,4% sau thuế. Chia hệ số tăng trưởng sau thuế 1,024 cho hệ số lạm phát 1,02 rồi trừ 1, được khoảng 0,39%. Thuế phụ thuộc hoàn cảnh nhà đầu tư nên một con số báo cáo chung không nhất thiết áp dụng cho tất cả.'],
 17:['For borrowed capital, distinguish total invested assets from equity. In the source example, a EUR10 million position financed with EUR3 million debt leaves EUR7 million equity. The asset return is 8%, while the debt costs 5%; the positive spread of 3 percentage points is multiplied by debt/equity (3/7). The resulting equity return is 9.29%. If the asset return falls below the borrowing rate, leverage instead reduces the investor’s return.','Với vốn vay, cần phân biệt tổng tài sản đầu tư và vốn chủ sở hữu. Trong ví dụ nguồn, danh mục 10 triệu EUR được tài trợ bằng 3 triệu EUR nợ, còn 7 triệu EUR vốn chủ. Lợi suất tài sản 8%, chi phí vay 5%; chênh lệch dương 3 điểm phần trăm được nhân với tỷ lệ nợ/vốn chủ (3/7). Kết quả là lợi suất trên vốn chủ 9,29%. Nếu lợi suất tài sản thấp hơn lãi vay, đòn bẩy ngược lại làm giảm lợi suất của nhà đầu tư.']
};

const ratesHeads={a:'Interest Rates and Time Value of Money',b:'Rates of Return',c:'Money-Weighted and Time-Weighted Return',d:'Annualized Return',e:'Other Major Return Measures and Their Applications'};
// Explicit placement for the checked Rates and Returns source cards (CFAI PDF pp.13–45).
const ratesF=[[0,1],[2,3,4,5,6,15],[7,8,16],[9,10,17,11],[12,18,13,19,14,20]], ratesE=[[7],[0,8,18,1,9,2,10],[19,3,11,12,13],[14,4,15],[17,5,6,16]];
const ratesFTopic=[2,2,3,3,4,5,6,8,9,11,12,13,14,16,17,6,9,12,15,16,17],ratesETopic=[3,5,6,8,12,16,17,2,3,5,6,8,10,10,11,12,17,16,5,8];
const lectureFormula=(f,d)=>`<div class="v142-formula"><h4>${esc(f[0])}</h4><div class="v14-equation">${esc(f[1])}</div>${pair(f[2],f[3])}<div class="v142-reference">${f[4]?`<small>Source · PDF p. ${esc(f[4])}</small>`:''}${orig('View source',f[5]||d.source,f[4],'quiet')}</div></div>`;
const lectureExample=(x,d)=>`<div class="v142-example"><h4>${esc(x[0])}</h4>${pair(x[1],x[2])}<div class="v142-solution"><strong>Solution</strong><div class="v14-equation">${esc(x[3])}</div><p><strong>Answer:</strong> ${esc(x[4])}</p></div><div class="v142-reference">${x[5]?`<small>Source · PDF p. ${esc(x[5])}</small>`:''}${orig('View source',x[6]||d.source,x[5],'quiet')}</div></div>`;
function lecture(m,d,rows,n){
 const pilot=m.id==='CFA26-01-01';
 const groups=[];for(let i=0;i<rows.length;i++){const r=rows[i],k=String(r.los||'');let g=groups.find(x=>x.key===k);if(!g){const base=d.sections?.find(x=>String(x[0])===k);g={key:k,title:pilot?ratesHeads[k]:base?.[1]||r.title,rows:[],formulas:[],examples:[]};groups.push(g)}g.rows.push({...r,index:i})}
 // Map only unambiguous page-range matches. Ambiguous or different-source cards remain visible below.
 const other={formulas:[],examples:[]};
 const assign=(card,i,type)=>{let pg=Number(card[type==='formulas'?4:5]),sid=card[type==='formulas'?5:6]||d.source;let matches=groups.filter(g=>sid===d.source&&g.rows.some(r=>Number(r.start)<=pg&&pg<=Number(r.end)));if(pilot){let idx=(type==='formulas'?ratesF:ratesE).findIndex(a=>a.includes(i));matches=idx>=0?[groups[idx]]:[];}if(matches.length===1&&matches[0])matches[0][type].push(card);else other[type].push(card)};
 (d.formulas||[]).forEach((f,i)=>assign(f,i,'formulas'));(d.examples||[]).forEach((x,i)=>assign(x,i,'examples'));
 // For each chapter, place the source formula/example immediately after the closest relevant subsection.
 const chapter=g=>{let bins=g.rows.map(r=>({r,formulas:[],examples:[]}));const place=(x,type)=>{const pg=Number(x[type==='formulas'?4:5]);let hit=bins.filter(b=>Number(b.r.start)<=pg&&pg<=Number(b.r.end));let target=hit.length?hit[hit.length-1]:bins[bins.length-1];if(pilot){let index=(type==='formulas'?d.formulas:d.examples).indexOf(x),topic=(type==='formulas'?ratesFTopic:ratesETopic)[index];target=bins.find(b=>b.r.index===topic)||target}target[type].push(x)};g.formulas.forEach(f=>place(f,'formulas'));g.examples.forEach(x=>place(x,'examples'));return bins.map(({r,formulas,examples})=>`<div class="v142-topic" id="lecture-part-${r.index}"><h3>${esc(r.title)}</h3>${S.language!=='en'&&r.viTitle?`<p class="v142-translation">${esc(r.viTitle)}</p>`:''}${pair(r.en,r.vi)}${pilot&&ratesDetail[r.index]?pair(...ratesDetail[r.index]):''}${formulas.map(f=>lectureFormula(f,d)).join('')}${examples.map(x=>lectureExample(x,d)).join('')}</div>`).join('')};
 const extras=other.formulas.length||other.examples.length;
 const toc=[...groups.map((g,i)=>({title:g.title,id:`lecture-chapter-${i}`})),...(extras?[{title:'Additional Formulas & Examples',id:'lecture-additional'}]:[]),{title:'Key Takeaways',id:'lecture-end'}];
 const sourcePage=g=>g.rows.find(r=>r.start)?.start;
 const note=pilot?'Bài giảng mẫu: mạch dẫn được viết lại từ CFAI Curriculum 2026, PDF trang 13–45; công thức và ví dụ lấy từ các thẻ nguồn đã đối chiếu.':'Bản bài giảng liên tục từ các nhóm kiến thức đã đối chiếu. Mức độ chi tiết hiện vẫn là tóm lược, chưa thay thế toàn bộ nội dung nguồn.';
 const header=`<header class="v142-intro"><p class="v142-kicker">LEARNING MODULE ${m.number} · LESSON</p><p>${esc(note)}</p><details class="v142-objectives"><summary>Learning Objectives</summary><ol>${m.los.map(l=>`<li>${esc(l.title)}</li>`).join('')}</ol></details></header>`;
 const takeaways=`<section id="lecture-end" class="v142-chapter"><h2>Key Takeaways</h2>${(d.sections||[]).map(x=>`<h3>${esc(x[1])}</h3>${pair(x[3],x[4])}`).join('')}${(d.traps||[]).length?`<h3>Common Mistakes</h3><div class="v142-mistakes">${d.traps.map(x=>`<div><strong>${esc(x[0])}</strong>${pair(x[1],x[2])}</div>`).join('')}</div>`:''}${(d.notes||[]).length?`<details class="v142-objectives"><summary>Source Notes &amp; Corrections</summary>${d.notes.map(x=>`<h4>${esc(x[0])}</h4>${pair(x[1],x[2])}`).join('')}</details>`:''}<div class="v14-actions end">${link('Practice this module →',hash('module',m.id,'questions',0),'primary')}</div></section>`;
 return `<div class="v14-lesson-layout v142-layout"><aside class="v14-toc v142-toc"><div class="v14-toc-head">Contents</div>${toc.map((t,i)=>`<button type="button" class="v142-jump" data-lecture-jump="${t.id}"><span>${i+1}.</span><span>${esc(t.title)}</span></button>`).join('')}</aside><article class="v14-lesson v142-article">${header}${groups.map((g,i)=>`<section class="v142-chapter" id="lecture-chapter-${i}"><h2><span>${i+1}.</span> ${esc(g.title)}</h2>${pilot&&ratesLead[g.key]?pair(...ratesLead[g.key]):''}${chapter(g)}<div class="v142-chapter-source">${orig('Read original source',d.source,sourcePage(g),'quiet')}</div></section>`).join('')}${extras?`<section class="v142-chapter" id="lecture-additional"><h2>Additional Formulas &amp; Examples</h2>${other.formulas.map(f=>lectureFormula(f,d)).join('')}${other.examples.map(x=>lectureExample(x,d)).join('')}</section>`:''}${takeaways}</article></div>`;
}

function modulePage(id,tab,part){let m=M[id];if(!m)return study();if(!tabs.some(t=>t[0]===tab))tab='learn';if(id==='CFA26-01-01'&&tab==='learn'&&part!=='legacy'&&window.CFA_RATES_PROTOTYPE){S.last={id,tab,part:part||0};save();window.CFA_RATES_PROTOTYPE.render(root,part);return;}const d=R.modules[id],s=SM[m.subject_code],rows=d.coverageAudit?.rows||d.sections.map(x=>({los:x[0],title:x[1],viTitle:x[2],en:x[3],vi:x[4],start:x[5],end:x[6]}));const n=Math.min(Math.max(0,Number(part)||0),Math.max(0,rows.length-1));S.last={id,tab,part:n};save();let next=s.modules[s.modules.indexOf(m)+1];root.innerHTML=crumb(s,m)+title(m.title,`Module ${m.number} · ${s.en}`,language())+sourceLine(m,d)+`<div class="v14-tabbar" role="navigation" aria-label="Các bước học module">${tabs.map(([k,t])=>`<a href="${hash('module',id,k,0)}" class="${tab===k?'active':''}" ${tab===k?'aria-current="page"':''}>${t}</a>`).join('')}</div><div id="v14-module-body"></div><div class="v14-complete"><div><strong>${isDone(m)?'Module đã hoàn thành':'Bạn đã học xong module?'}</strong><p>Đánh dấu thủ công sau khi học và luyện tập.</p></div>${btn(isDone(m)?'Bỏ đánh dấu':'Đánh dấu đã học','mark','secondary',`data-id="${id}"`)}${next?link('Next module →',hash('module',next.id,'learn',0),'primary'):link('Back to modules',hash('subject',s.code),'primary')}</div>`;let body=$('v14-module-body');if(tab==='learn'){body.innerHTML=lecture(m,d,rows,n);if(n>0)requestAnimationFrame(()=>document.getElementById('lecture-part-'+n)?.scrollIntoView({block:'start'}));}else if(tab==='formula'){body.innerHTML=section('Formulas & Rules',d.formulas?.length?`<div class="v14-content-grid">${d.formulas.map(f=>`<article class="v14-content"><h3>${esc(f[0])}</h3><div class="v14-equation">${esc(f[1])}</div>${pair(f[2],f[3])}${orig('Xem nguồn',f[5]||d.source,f[4])}</article>`).join('')}</div>`:'<p class="v14-empty">Module này không có công thức định lượng riêng. Xem các quy tắc trong lý thuyết.</p>')+section('Worked Examples',`<div class="v14-content-grid">${(d.examples||[]).map(x=>`<article class="v14-content"><h3>${esc(x[0])}</h3>${pair(x[1],x[2])}<details class="v14-details"><summary>Xem cách giải và kết quả</summary><div class="v14-equation">${esc(x[3])}</div><p><strong>Kết quả:</strong> ${esc(x[4])}</p></details>${orig('Xem ví dụ gốc',x[6]||d.source,x[5])}</article>`).join('')||'<p class="v14-empty">Đọc ví dụ trong tài liệu gốc.</p>'}</div>`)+`<div class="v14-actions end">${link('Next: Review →',hash('module',id,'recap',0),'primary')}</div>`}else if(tab==='recap'){let sup=R.supplement137?.[s.code]?.mindmap?.filter(x=>x.modules.includes(m.number))||[];body.innerHTML=section('Key Concepts',`<div class="v14-content-grid">${(d.sections||[]).map(x=>`<article class="v14-content"><h3>${esc(x[1])}</h3>${pair(x[3],x[4])}</article>`).join('')}</div>`)+section('Nhầm lẫn thường gặp',`<div class="v14-content-grid">${(d.traps||[]).map(x=>`<article class="v14-content"><h3>${esc(x[0])}</h3>${pair(x[1],x[2])}</article>`).join('')}</div>`)+section('Mindmap',`<div class="v14-content">${sup.map(x=>`<h3>${esc(x.title)}</h3>${pair(x.en,x.vi)}`).join('')}${orig('Mở sơ đồ tư duy nguyên bản',B.mindmap134?.[s.code],1,'secondary')}</div>`)+section('Thuật ngữ',`<div class="v14-content">${(d.glossary||[]).map(x=>`<div class="v14-gloss"><strong>${esc(x[0])}</strong>${pair(x[1],x[2])}</div>`).join('')}</div>`)+`<div class="v14-actions end">${link('Next: Practice →',hash('module',id,'questions',0),'primary')}</div>`}else{body.innerHTML=`<div class="v14-content"><h2>Luyện câu hỏi của module này</h2><p>Chọn nguồn, số câu, rồi bắt đầu. Đề bằng tiếng Anh, lời giải theo tài liệu gốc.</p><div id="practice-builder"></div></div>`;buildPractice(m.id)}}
function summary(code){const s=SM[code];if(!s)return study();let d=R.subjects[code],sup=R.supplement137?.[code];root.innerHTML=crumb(s)+title(s.en+' — Subject Review',s.vi,language())+`<div class="v14-actions">${orig('Mở Mindmap nguyên bản',B.mindmap134?.[code],1,'secondary')}${orig('Mở Kaplan QuickSheet','SRC-0133',1,'secondary')}${link('Luyện câu theo môn',hash('practice',code),'primary')}</div>`+section('Key Concepts',`<div class="v14-content-grid">${d.keys.map(x=>`<article class="v14-content"><h3>${esc(x[1])}</h3>${pair(x[2],x[3])}${link('Học module '+x[0],hash('module',s.modules.find(m=>m.number===x[0])?.id||s.modules[0].id,'learn',0))}</article>`).join('')}</div>`)+section('Mindmap & QuickSheet',`<div class="v14-content-grid">${[...(sup?.mindmap||[]),...(sup?.quick||[])].map(x=>`<article class="v14-content"><h3>${esc(x.title)}</h3>${pair(x.en,x.vi)}${orig('Xem nguồn',x.source,x.page)}</article>`).join('')}</div>`)+section('Formulas by Module',`<div class="v14-content">${(d.formulaGroups||[]).map(g=>`<details class="v14-details"><summary>Module ${g.module} · ${g.cards.length} mục</summary>${g.cards.map(x=>`<div class="v14-gloss"><strong>${esc(x[0])}</strong><div class="v14-equation">${esc(x[1])}</div>${pair(x[2],x[3])}</div>`).join('')}</details>`).join('')}</div>`)}
function practice(code){root.innerHTML=title('Question Bank','Chọn môn hoặc module, nguồn câu hỏi và số lượng. Không dùng câu tự biên soạn mặc định.')+`<div class="v14-content v14-builder"><div id="practice-builder"></div></div>`;buildPractice(null,SM[code]?code:'all')}
let practiceRows=[];
let refreshPractice=null;
function buildPractice(mid=null,code='all'){const holder=$('practice-builder');holder.innerHTML=`<form id="practice-form" class="v14-form"><div class="v14-form-grid">${mid?'':`<label>Môn học<select id="p-subject"><option value="all">Tất cả môn</option>${subjects.map(s=>`<option value="${s.code}" ${code===s.code?'selected':''}>${esc(s.en)}</option>`).join('')}</select></label><label>Module<select id="p-module"><option value="all">Tất cả module</option></select></label>`}<label>Nguồn câu hỏi<select id="p-source"><option value="all">Tất cả nguồn câu hỏi</option><option value="CFAI Curriculum">CFA Institute</option><option value="Kaplan QBank">Kaplan QBank</option><option value="Bonus QBank">Question Bank bổ sung</option></select></label><label>Trạng thái<select id="p-status"><option value="all">Tất cả</option><option value="new">Chưa trả lời</option><option value="wrong">Đã tự chấm sai / chưa chắc</option><option value="saved">Đã lưu</option></select></label><label>Số câu<select id="p-count"><option value="10">10 câu</option><option value="20">20 câu</option><option value="40">40 câu</option><option value="all">Tất cả câu khớp bộ lọc</option></select></label><label>Thứ tự<select id="p-order"><option value="source">Theo thứ tự nguồn</option><option value="random">Xáo trộn</option></select></label></div><div class="v14-builder-bottom"><div><strong id="p-available" aria-live="polite"></strong><p class="v14-hint">Tự chấm theo lời giải nguồn. Bài tự luận không ép chọn A/B/C.</p></div><button type="submit" id="p-start" class="v14-btn primary">Bắt đầu luyện</button></div></form>`;const updateModules=()=>{if(mid)return;let s=$('p-subject').value,ms=s==='all'?I:SM[s].modules;$('p-module').innerHTML='<option value="all">Tất cả module</option>'+ms.map(m=>`<option value="${m.id}">${esc(s==='all'?m.subject+' · ': '')}LM${m.number} · ${esc(m.title)}</option>`).join('')};const update=()=>{let s=mid?M[mid].subject_code:$('p-subject').value,m=mid||$('p-module').value,g=$('p-source').value,t=$('p-status').value,p=progress();practiceRows=(m!=='all'?(itemsByModule.get(m)||[]):all.filter(e=>moduleId(e)&&(s==='all'||M[moduleId(e)].subject_code===s))).filter(e=>group(e)!=='Mock Test'&&(g==='all'||group(e)===g)&&(t==='all'||t==='new'&&!p[e.id]?.choice&&!p[e.id]?.grade||t==='wrong'&&['wrong','review'].includes(p[e.id]?.grade)||t==='saved'&&p[e.id]?.saved));$('p-available').textContent=`${fmt(practiceRows.length)} câu/định vị phù hợp`; $('p-start').disabled=!practiceRows.length;};updateModules();update();refreshPractice=update;holder.addEventListener('change',e=>{if(e.target.id==='p-subject')updateModules();update()});holder.querySelector('form').addEventListener('submit',e=>{e.preventDefault();let rows=practiceRows.slice();if($('p-order').value==='random')for(let i=rows.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[rows[i],rows[j]]=[rows[j],rows[i]]}let n=$('p-count').value;rows=n==='all'?rows:rows.slice(0,Number(n));if(rows.length)window.CFA_PRIVATE_START(rows.map(x=>x.id),'Luyện câu hỏi')})}
function mock(){root.innerHTML=title('Mock Exams','Chọn một phiên đề nguyên bản. Không trộn các đề hoặc năm khác nhau.')+`<div class="v14-content"><label class="v14-search-label">Tìm theo tên nguồn hoặc năm<input id="mock-search" placeholder="Ví dụ: Kaplan, 2020, FinQuiz"></label><p class="v14-hint">Đây là chế độ luyện từng phiên đề gốc, tự chấm theo lời giải; chưa phải mô phỏng thi có chấm điểm và đồng hồ.</p></div><div id="mock-list" class="v14-list"></div>`;const update=()=>{let q=$('mock-search').value.toLowerCase().trim();$('mock-list').innerHTML=[...mockBySource].filter(([id,rs])=>`${B.files[id].path} ${rs[0].topic}`.toLowerCase().includes(q)).map(([id,rs])=>`<article class="v14-module-row"><span class="v14-module-num">${icon('clock')}</span><div><h3>${esc(rs[0].topic||B.files[id].name)}</h3><p>${esc(B.files[id].name)} · ${rs.length} câu</p></div>${btn('Mở phiên đề','mock-start','primary',`data-id="${esc(id)}"`)}</article>`).join('')||'<div class="v14-empty">Không có đề khớp từ khóa.</div>'};$('mock-search').oninput=update;update()}
function review(){let p=progress(),rows=allRecords.filter(e=>p[e.id]?.saved||['wrong','review'].includes(p[e.id]?.grade)),wrong=rows.filter(e=>p[e.id]?.grade==='wrong').length,unsure=rows.filter(e=>p[e.id]?.grade==='review').length,saved=rows.filter(e=>p[e.id]?.saved).length;root.innerHTML=title('Review','Xem lại câu đã lưu, tự chấm sai hoặc đánh dấu chưa chắc.')+`<div class="v14-content"><h2>Rates and Returns · Knowledge Checks</h2><p>Review saved and incorrect checks from the pilot lesson.</p>${link('Open lesson review', '#module/CFA26-01-01/learn/rp-review','primary')}</div>`+`<div class="v14-statgrid"><div><strong>${wrong}</strong><span>Câu sai</span></div><div><strong>${unsure}</strong><span>Chưa chắc</span></div><div><strong>${saved}</strong><span>Đã lưu</span></div></div>${rows.length?`<div class="v14-actions">${btn('Ôn tất cả '+rows.length+' câu','review-start','primary')}${wrong?btn('Chỉ ôn câu sai','review-wrong','secondary'):''}</div><div class="v14-list">${rows.map(e=>`<article class="v14-module-row"><div><h3>${esc(e.topic||B.files[e.source].name)} · Question ${e.number}</h3><p>${esc(sourceLabel(group(e)))} · ${p[e.id]?.grade==='wrong'?'Sai':p[e.id]?.grade==='review'?'Chưa chắc':'Đã lưu'}</p></div>${btn('Ôn câu này','review-one','secondary',`data-id="${esc(e.id)}"`)}</article>`).join('')}</div>`:`<div class="v14-empty"><h2>Chưa có câu cần ôn</h2><p>Sau khi luyện, chọn “Tự chấm: sai”, “Chưa chắc” hoặc lưu câu hỏi. Các câu đó sẽ xuất hiện ở đây.</p>${link('Bắt đầu luyện câu hỏi','#practice','primary')}</div>`}`}
function settings(){root.innerHTML=title('Settings','Quản lý dữ liệu trên thiết bị. Không cần vào đây khi học hàng ngày.')+`<section class="v14-content"><h2>Học liệu cá nhân</h2><p data-private-cache-status>Đang kiểm tra học liệu…</p><p>Gói v13.7 chứa nguyên văn đề, lời giải và tài liệu. Chọn một lần trên mỗi trình duyệt; nếu đã lưu, website tự đọc lại.</p><div class="v14-actions"><button class="v14-btn primary" data-private-library>Thiết lập / mở thư viện gốc</button><button class="v14-btn" data-private-search>Tìm trong toàn văn nguồn</button></div><p class="v14-hint">Không gửi file lên mạng. Nếu xóa dữ liệu trang hoặc dùng thiết bị khác, cần chọn lại.</p></section><section class="v14-content"><h2>Hiển thị</h2>${language()}${btn(S.dark?'Dùng giao diện sáng':'Dùng giao diện tối','theme')}</section><section class="v14-content"><h2>Kiến thức nền và tài liệu bổ trợ</h2>${subjects.map(s=>{let p=R.supplement137?.[s.code]?.prerequisite||[];return p.length?`<details class="v14-details"><summary>${esc(s.en)} · ${p.length} bài nền</summary>${p.map(x=>`<h3>${esc(x.title)}</h3>${pair(x.en,x.vi)}${orig('Xem nguồn',x.source,x.page)}</details>`).join('')}`:''}).join('')}<button class="v14-btn" data-private-library>Toàn bộ 534 tài liệu gốc</button></section><section class="v14-content"><h2>Tiến độ và chức năng cũ</h2><div class="v14-actions">${btn('Xuất tiến độ học mới','export','secondary')}${link('Giao diện v13.8 / công cụ cũ','study-archive.html#home')}${link('Bài tự biên soạn cũ','study-archive.html#quiz')}</div><p class="v14-hint">Dữ liệu cũ vẫn giữ nguyên. Bản này thay đổi luồng học, không tăng độ bao phủ nội dung.</p></section>`;window.CFA_LOCAL_LIBRARY_STATUS?.()}

const docSubjects=new Map();function associate(id,code){if(!id||!code)return;if(!docSubjects.has(id))docSubjects.set(id,new Set());docSubjects.get(id).add(code)}
for(const [id,f] of Object.entries(B.files))associate(id,f.subject);
for(const o of B.outline){associate(o.curriculum?.source,o.subject);associate(o.kaplan?.source,o.subject);associate(B.slideModules134?.[o.id]?.source,o.subject)}
for(const [c,id] of Object.entries(B.mindmap134||{}))associate(id,c);
for(const e of all){const c=M[moduleId(e)]?.subject_code;associate(e.source,c);associate(e.answer,c)}
const groups=['CFAI Curriculum','Kaplan SchweserNotes','SAPP Slides','Revision Mindmap','CFAI Prerequisite','Kaplan QBank','Bonus QBank','Mock Test'];
const docs=Object.entries(B.files).sort((a,b)=>groups.indexOf(a[1].group)-groups.indexOf(b[1].group)||a[1].path.localeCompare(b[1].path,undefined,{numeric:true}));
const docLabel=g=>({'CFAI Curriculum':'CFAI Curriculum','Kaplan SchweserNotes':'Kaplan SchweserNotes & QuickSheet','Revision Mindmap':'Revision Mindmaps','SAPP Slides':'SAPP Slides','CFAI Prerequisite':'Prerequisite Reading','Kaplan QBank':'Kaplan Question Bank','Bonus QBank':'Bonus Question Bank','Mock Test':'Mock Exams'}[g]||g);
const norm=x=>String(x??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const docTitle=(id,f)=>{const cs=[...(docSubjects.get(id)||[])];if(cs.length===1&&['CFAI Curriculum','SAPP Slides','Revision Mindmap','CFAI Prerequisite'].includes(f.group))return SM[cs[0]]?.en+' — '+docLabel(f.group);if(id==='SRC-0132')return 'CFAI Glossary';if(id==='SRC-0133')return 'Kaplan Schweser QuickSheet';return f.name.replace(/\.pdf$/i,'').replace(/_/g,' ')};
const matchDoc=(id,f,q)=>norm([f.name,f.path,docLabel(f.group),...[...(docSubjects.get(id)||[])].map(c=>SM[c]?.en)].join(' ')).includes(norm(q));
function library(code='all',q=''){let page=0;root.innerHTML=title('Library','Tất cả 534 tài liệu gốc. Chọn nhóm hoặc môn, rồi bấm Read.')+`<div class="v141-start"><div><strong>Local study data</strong><p data-private-cache-status>Checking local data…</p></div><button class="v14-btn secondary" data-private-library>Load study data</button><button class="v14-btn" data-private-search>Full-text search</button></div><div class="v141-filters"><label>Search documents<input id="lib-query" type="search" value="${esc(q)}" placeholder="SchweserNotes, Quant, 2026…"></label><label>Subject<select id="lib-subject"><option value="all">All subjects</option>${subjects.map(s=>`<option value="${s.code}" ${code===s.code?'selected':''}>${esc(s.en)}</option>`).join('')}</select></label><label>Source<select id="lib-group"><option value="all">All sources</option>${groups.map(g=>`<option value="${esc(g)}">${esc(docLabel(g))}</option>`).join('')}</select></label></div><div class="v141-chips">${groups.map(g=>`<button type="button" class="v14-btn quiet" data-lib-group="${esc(g)}">${esc(docLabel(g))} · ${docs.filter(([,f])=>f.group===g).length}</button>`).join('')}</div><div id="lib-results"></div>`;
const update=()=>{const c=$('lib-subject').value,g=$('lib-group').value,q=$('lib-query').value.trim(),rows=docs.filter(([id,f])=>(c==='all'||docSubjects.get(id)?.has(c))&&(g==='all'||f.group===g)&&matchDoc(id,f,q));const size=25,max=Math.max(0,Math.ceil(rows.length/size)-1);page=Math.min(page,max);$('lib-results').innerHTML=`<div class="v141-resulthead"><strong>${rows.length} documents</strong><span>${rows.length?page*size+1:0}–${Math.min((page+1)*size,rows.length)} of ${rows.length}</span></div><div class="v141-doclist">${rows.slice(page*size,(page+1)*size).map(([id,f])=>`<article class="v141-document"><div><h3>${esc(docTitle(id,f))}</h3><p>${esc(f.name)} · ${f.scan134?.pages||f.scan133?.pages||'?'} pages</p></div>${orig('Read',id,1,'primary')}</article>`).join('')||'<p class="v14-empty">No matching documents.</p>'}</div><div class="v14-actions"><button id="lib-prev" class="v14-btn" ${page===0?'disabled':''}>Previous</button><button id="lib-next" class="v14-btn" ${page>=max?'disabled':''}>Next</button></div>`;$('lib-prev').onclick=()=>{page--;update()};$('lib-next').onclick=()=>{page++;update()}};
for(const id of ['lib-query','lib-subject','lib-group'])$(id).addEventListener(id==='lib-query'?'input':'change',()=>{page=0;update()});root.querySelectorAll('[data-lib-group]').forEach(b=>b.onclick=()=>{$('lib-group').value=b.dataset.libGroup;page=0;update()});update();window.CFA_LOCAL_LIBRARY_STATUS?.()}
function search(q){const pilotMatches=window.CFA_RATES_PROTOTYPE?.search(q)||[];let n=(q||'').trim().toLowerCase(),rows=I.filter(m=>`${m.title} ${m.subject} ${SM[m.subject_code].vi} ${m.los.map(l=>l.title).join(' ')}`.toLowerCase().includes(n));root.innerHTML=title('Search Results',`${rows.length} matching modules · ${docs.filter(([id,f])=>matchDoc(id,f,q)).length} matching documents`,link('Search documents',hash('library','all',q),'primary'))+(pilotMatches.length?`<section class="v14-content"><h2>Concept & formula matches · Rates and Returns</h2>${pilotMatches.map(x=>`<p><a href="${esc(x.url)}">${esc(x.title)} · LOS ${esc(x.los.toUpperCase())}</a></p>`).join('')}</section>`:'')+`<div class="v14-list">${rows.map(m=>`<a class="v14-module-row" href="${hash('module',m.id,'learn',0)}"><span class="v14-module-num">${m.number}</span><div><h3>${esc(m.title)}</h3><p>${esc(SM[m.subject_code].vi)}</p></div>${icon('arrow')}</a>`).join('')||'<div class="v14-empty">Không tìm thấy module. Thử từ khóa tiếng Anh.</div>'}</div><div class="v14-actions"><button class="v14-btn" data-private-search>Tìm trong toàn văn tài liệu</button></div>`}
function render(){window.CFA_RATES_PROTOTYPE?.cleanup(root);refreshPractice=null;let [p='home',a,b,c]=location.hash.slice(1).split('/').map(x=>{try{return decodeURIComponent(x)}catch{return x}});if(!p)p='home';if(p==='book')p='study';if(p==='course')p='subject';if(p==='recap'){if(M[a]){p='module';b='recap'}else if(SM[a])p='summary';else p='study'}if(p==='lesson'&&L[a]){a=L[a].id;p='module';b='learn'}if(p==='sourcebank'){if(M[a]){p='module';b='questions'}else if(L[a]){a=L[a].id;p='module';b='questions'}else{p='library';a=SM[a]?a:'all'}}if(p==='quiz'||p==='lab'){location.href='study-archive.html'+location.hash;return}shell(['home','subject','module','summary','search'].includes(p)?'study':p);try{switch(p){case'study':study();break;case'library':library(a,b);break;case'subject':subject(a);break;case'module':modulePage(a,b,c);break;case'summary':summary(a);break;case'practice':practice(a);break;case'mock':mock();break;case'review':review();break;case'settings':settings();break;case'search':search(a);break;default:home()}}catch(e){console.error(e);root.innerHTML=title('Không mở được trang')+`<p>${esc(e.message)}</p>${link('Về trang chủ','#home','primary')}`};document.title='Study Hub 15.0 Pilot · '+($('v14-top')?.textContent.trim()||'CFA Level I');window.scrollTo(0,0)}
document.addEventListener('click',e=>{let j=e.target.closest('[data-lecture-jump]');if(j){document.getElementById(j.dataset.lectureJump)?.scrollIntoView({block:'start',behavior:'smooth'});root.querySelectorAll('[data-lecture-jump]').forEach(x=>x.classList.toggle('current',x===j));return}let b=e.target.closest('[data-action]');if(!b)return;let a=b.dataset.action;if(a==='theme'){S.dark=!S.dark;save();render()}else if(a==='mark'){let id=b.dataset.id;S.done[id]=!isDone(M[id]);if(!S.done[id]&&M[id].los.every(l=>legacy.read?.[l.id]))S.done[id]=false;save();render()}else if(a==='mock-start'){const rows=(mockBySource.get(b.dataset.id)||[]).slice().sort((x,y)=>x.number-y.number);window.CFA_PRIVATE_START(rows.map(x=>x.id),'Luyện phiên đề')}else if(a==='review-start'||a==='review-wrong'||a==='review-one'){let p=progress(),rows=allRecords.filter(x=>a==='review-one'?x.id===b.dataset.id:a==='review-wrong'?p[x.id]?.grade==='wrong':p[x.id]?.saved||['wrong','review'].includes(p[x.id]?.grade));window.CFA_PRIVATE_START(rows.map(x=>x.id),'Ôn câu hỏi')}else if(a==='export'){let blob=new Blob([JSON.stringify({version:14,study:S,sourceProgress:progress()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),l=document.createElement('a');l.href=url;l.download='CFA-study-progress-v14.json';l.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}});
document.addEventListener('submit',e=>{if(e.target.id==='global-search'){e.preventDefault();go('search',$('search-input').value.trim())}});document.addEventListener('change',e=>{if(e.target.id==='language'){S.language=e.target.value;save();render()}});document.addEventListener('cfa-private-closed',()=>{if(refreshPractice&&$('p-available'))refreshPractice();else if(location.hash.slice(1).split('/')[0]==='library')window.CFA_LOCAL_LIBRARY_STATUS?.();else if(['home','review','settings'].includes(location.hash.slice(1).split('/')[0]))render()});window.addEventListener('hashchange',render);render();
})();
